/** Source-pinned real environmental evidence, research receipts not real-time forecasts.
 * Both JSON reports were generated by read-only CI calls and returned HOLD.
 * Git blob checks authenticate exact reviewed bytes, NOT their upstream agency
 * provenance or an independent recomputation of source measurements.
 */
import {readFile} from "node:fs/promises";
import {createHash} from "node:crypto";
import {inspectEventLearning} from "./motif-event-lessons.mjs";
import {inspectQuestionAboutQuestion} from "./motif-question-about-question.mjs";
import {inspectEmbodied} from "./motif-embodied-resource.mjs";
import {inspectProtocolIntegrity} from "./motif-protocol-integrity.mjs";
export const WITNESS_SOURCES=Object.freeze({
  watershed:{url:new URL("../integrations/motif-reality-016/actual-watershed-2026-11-05.json",import.meta.url),
    blob:"8e0f7c9123a9d12b0ffcc95c449e4d20bd8bcfeb",schema:"motif.reality-iron-watershed/v1"},
  weather:{url:new URL("../integrations/motif-reality-016/actual-weather-2026-11-05.json",import.meta.url),
    blob:"a57535a31da37bf9caee4cd3feaf009941749b6f",schema:"motif.reality-iron-weather/v1"}
});
const hold=reason=>Object.assign(new Error("HOLD: "+reason),{status:409});
const finite=x=>typeof x==="number"&&Number.isFinite(x);
const citation="https://github.com/the-static-collective/MOTIF/actions/runs/42030670309";
export const RESEARCH_RECEIPT_COMMIT="23267b297094012d81525ddef2c5c36d6a5560b2";
function validDigest(x){return typeof x==="string"&&/^[0-9a-f]{64}$/.test(x);}
export function inspectEvidenceBodies(water,weather){
  if(water?.schema!=="motif.reality-iron-watershed/v1"||
     water.scope!=="RETROSPECTIVE_REAL_SENSOR_TEST_NOT_DEPLOYED_FORECAST"||
     water.real_world_effect!==false||water.automatic_promotion!==false||
     water.authority!==false||water.independent_outcome_verified!==false||
     water.provenance?.USGS_public_site_ids?.blue!=="USGS-05320000"||
     water.provenance?.USGS_public_site_ids?.sueur!=="USGS-05320500"||
     water.provenance?.USGS_public_site_ids?.mankato!=="USGS-05325000"||
     !Object.values(water.provenance?.source_json_sha256||{}).every(validDigest)||
     Object.keys(water.provenance?.source_json_sha256||{}).length!==4||
     !Number.isInteger(water.matched_complete_hours)||water.matched_complete_hours<80||
     !Object.values(water.partitions||{}).every(Number.isInteger)||
     (water.partitions?.train+water.partitions?.validation+water.partitions?.test)!==water.matched_complete_hours||
     typeof water.selected_on_validation!=="string"||
     !finite(water.holdout_mae_cfs?.persistence)||
     !finite(water.holdout_mae_cfs?.[water.selected_on_validation])||
     !finite(water.validation_mae_cfs?.persistence)||
     !finite(water.validation_mae_cfs?.[water.selected_on_validation])||
     !finite(water.holdout_improvement_vs_persistence_cfs)||
     Math.abs((water.holdout_mae_cfs.persistence-
       water.holdout_mae_cfs[water.selected_on_validation])-
       water.holdout_improvement_vs_persistence_cfs)>0.0003||
     water.disposition!=="HOLD_NO_IMPROVEMENT")throw hold("invalid source-owned watershed research receipt");

  if(weather?.schema!=="motif.reality-iron-weather/v1"||
     weather.station!=="KMKT"||
     weather.status!=="RETROSPECTIVE_OBSERVATIONAL_COMPARISON"||
     weather.real_world_effect!==false||weather.authority!==false||
     weather.automatic_promotion!==false||
     weather.improvement_disposition!=="HOLD_NO_MEASURED_IMPROVEMENT"||
     !validDigest(weather.provenance?.source_snapshots_sha256?.forecast)||
     !validDigest(weather.provenance?.source_snapshots_sha256?.observations)||
     !Number.isInteger(weather.matched_count)||weather.matched_count<24||
     weather.train_count+weather.test_count!==weather.matched_count||
     !finite(weather.holdout_mae_c?.raw_previous_day1)||
     !finite(weather.holdout_mae_c?.train_bias_adjusted)||
     weather.holdout_mae_c.train_bias_adjusted<
       weather.holdout_mae_c.raw_previous_day1)throw hold("invalid source-owned weather research receipt");

  const riverMargin=+(water.holdout_mae_cfs[water.selected_on_validation]-
      water.holdout_mae_cfs.persistence).toFixed(4);
  const weatherMargin=+(weather.holdout_mae_c.train_bias_adjusted-
      weather.holdout_mae_c.raw_previous_day1).toFixed(4);
  return {
    schema:"jarvis.motif-real-environment-witness/v1",
    status:"SOURCE_PINNED_RESEARCH_RECEIPTS_NOT_INDEPENDENTLY_RECOMPUTED",
    collectedAt:"2026-11-05",
    sourceExperiment:"MOTIF-015 + MOTIF-016",
    upstreamCommit:RESEARCH_RECEIPT_COMMIT,
    upstreamLiveRun:citation,
    sites:["USGS-05320000","USGS-05320500","USGS-05325000","NWS-KMKT"],
    watershed:{
      matchedHours:water.matched_complete_hours,
      train:water.partitions.train,validation:water.partitions.validation,
      test:water.partitions.test,
      selectedOnValidation:water.selected_on_validation,
      validationPersistenceCfs:water.validation_mae_cfs.persistence,
      validationCandidateCfs:water.validation_mae_cfs[water.selected_on_validation],
      holdoutPersistenceCfs:water.holdout_mae_cfs.persistence,
      holdoutCandidateCfs:water.holdout_mae_cfs[water.selected_on_validation],
      candidateExtraErrorCfs:riverMargin,
      risingEventTestHours:water.rising_event_test_scores?.persistence?.rising_count,
      disposition:water.disposition
    },
    weather:{
      matchedHours:weather.matched_count,train:weather.train_count,test:weather.test_count,
      holdoutRawC:weather.holdout_mae_c.raw_previous_day1,
      holdoutAdjustedC:weather.holdout_mae_c.train_bias_adjusted,
      adjustedExtraErrorC:weatherMargin,
      disposition:weather.improvement_disposition
    },
    reciprocalDisagreement:{
      motifToJarvis:"Environmental validation initially preferred the cross-gauge method, but the untouched river test favored simple persistence. A better-looking possibility was not a better predictor.",
      jarvisToMotif:"The number of hypothetical next routes is not a physical-world score. Neither a weather bias correction nor a multi-gauge fit deserves automatic admission.",
      diagnosticOnDiagnostic:"The evaluation needs hydrologic-event holdouts, station-availability checks, alternative regimes, and genuinely independent verification of raw source snapshots.",
      singleMostUsefulNextTest:"Freeze the methods; replicate over an independently collected rising-water episode before allowing a strategy upgrade."
    },
    improvements:[
      {target:"MOTIF",status:"HELD_FOR_REPLICATION",method:"Test event-blocked baselines, source-latency constraints, and strong physical hydrology controls."},
      {target:"JARVIS",status:"HELD_FOR_REPLICATION",method:"Favor evidence-bearing steps over route-count proxies; ask for independent measurements when uncertainty matters."}
    ],
    evidenceLimitations:[
      "Receipts are source-pinned Git blobs, but the raw USGS/Open-Meteo/NWS responses were not archived or independently recomputed here.",
      "Different stations share correlated weather and measurement procedures; not independent proof of causal effects.",
      "Historical gridded rain is an estimate, not a rain-gauge sensor.",
      "This prototype is retrospective and not a flood-warning or safety decision tool."
    ],
    sampledIndependently:false,realWorldActions:0,codeChanges:0,
    automaticPromotion:false,dispatch:false,authority:false
  };
}

export async function inspectRealityIron(){
  const bodies={};
  for(const [name,{url,blob,schema}] of Object.entries(WITNESS_SOURCES)){
    const buf=await readFile(url);
    const gitSha=createHash("sha1").update(Buffer.from("blob "+buf.length+"\0")).update(buf).digest("hex");
    if(gitSha!==blob)throw hold("environment evidence blob changed; review source");
    let value;
    try{value=JSON.parse(buf.toString("utf8"));}
    catch{throw hold("environment evidence JSON unavailable");}
    if(value?.schema!==schema)throw hold("unexpected environmental schema");
    bodies[name]=value;
  }
  return {...inspectEvidenceBodies(bodies.watershed,bodies.weather),
    eventLearning:await inspectEventLearning(),
    questionAboutQuestion:await inspectQuestionAboutQuestion(),
    embodiedResources:await inspectEmbodied(),
    protocolIntegrity:await inspectProtocolIntegrity(),
    sourceBlobs:Object.fromEntries(Object.entries(WITNESS_SOURCES).map(([n,v])=>[n,v.blob]))};
}
